import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// ConvTranspose3d specialized for:
//   kernel = 3x3x3, stride = 1, padding = 0, output_padding = 0,
//   dilation = 1, groups = 1, dtype = float32
//   in  : (N, 48, 96, 96, 96)  contiguous
//   w   : (48, 24, 3, 3, 3)    contiguous  (in_ch, out_ch, kD, kH, kW)
//   bias: (24,) or dummy
//   out : (N, 24, 98, 98, 98)  contiguous
// out[b,oc,z,y,x] = sum_{ic,kz,ky,kx} w[ic,oc,2-kz,2-ky,2-kx]
//                   * in[b,ic,z+kz-2,y+ky-2,x+kx-2]   (zero outside input)
//                 + bias[oc] (optional)
//
// Structural rewrite: CTA-level output-row-pair tiling with cooperative shared-memory
// input-row staging and register blocking over two rows.  Each CTA owns two adjacent
// (b,z,y) output rows (98 x-sites each); every thread keeps 2x24 output-channel
// accumulators for one x-site, while all 128 threads cooperatively stage the four
// reusable input rows for the current (ic,kz).  Both rows share each packed weight
// tap, halving shared-memory weight traffic and weight-staging work per output.
// Optimization: cp.async double-buffered software pipelining (sm_89 async copy).
// The next kz step's four input rows (16B chunks, zero-filled at edges) and the
// next input channel's transposed weight tile (4B async copies) are prefetched
// while the current stage computes.  Every kz iteration commits exactly one async
// group, so a single cp.async.wait_group 1 + bar.sync retires the stage prefetched
// in the previous iteration, overlapping global-memory staging with the FMA inner loop.
.visible .entry conv_transpose3d_k3_s1(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 has_bias
)
{
    .shared .align 16 .f32 wtile[1296];
    .shared .align 16 .f32 inrow[768];
    .reg .pred  %p<12>;
    .reg .b32   %r<48>;
    .reg .b64   %rd<24>;
    .reg .f32   %f<64>;
    ld.param.u64 %rd0, [in_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [bias_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r1,  [has_bias];
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    // decode ctaid -> b(r10), z(r12), y0(r13) = 2*(ctaid%49); CTA covers rows y0 and y0+1
    rem.u32 %r5, %r2, 49;                   // y-pair index inside the (b,z) plane
    div.u32 %r6, %r2, 49;
    rem.u32 %r12, %r6, 98;                  // z
    div.u32 %r10, %r6, 98;                  // b
    shl.b32 %r13, %r5, 1;                   // y0 = 2 * y-pair
    min.u32 %r14, %r4, 97;                  // inactive lanes compute dummy x=97
    setp.lt.u32 %p6, %r4, 98;               // active output-column lane
    // kz bounds: klo = max(0, 2 - z), khi = min(2, 97 - z) (shared by both rows)
    mov.s32 %r15, 2;
    sub.s32 %r15, %r15, %r12;
    max.s32 %r15, %r15, 0;                  // kz_lo
    mov.s32 %r16, 97;
    sub.s32 %r16, %r16, %r12;
    min.s32 %r16, %r16, 2;                  // kz_hi
    // kx bounds: klo = max(0, 2 - x), khi = min(2, 97 - x)
    mov.s32 %r19, 2;
    sub.s32 %r19, %r19, %r14;
    max.s32 %r19, %r19, 0;                  // kx_lo
    mov.s32 %r20, 97;
    sub.s32 %r20, %r20, %r14;
    min.s32 %r20, %r20, 2;                  // kx_hi
    // shared-memory base addresses in 32-bit space
    mov.u32 %r35, wtile;
    mov.u32 %r40, inrow;
    // 48 output-channel accumulators: row A f0..f23, row B f32..f55
    mov.f32 %f0,  0f00000000;
    mov.f32 %f1,  0f00000000;
    mov.f32 %f2,  0f00000000;
    mov.f32 %f3,  0f00000000;
    mov.f32 %f4,  0f00000000;
    mov.f32 %f5,  0f00000000;
    mov.f32 %f6,  0f00000000;
    mov.f32 %f7,  0f00000000;
    mov.f32 %f8,  0f00000000;
    mov.f32 %f9,  0f00000000;
    mov.f32 %f10, 0f00000000;
    mov.f32 %f11, 0f00000000;
    mov.f32 %f12, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.f32 %f21, 0f00000000;
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.f32 %f32, 0f00000000;
    mov.f32 %f33, 0f00000000;
    mov.f32 %f34, 0f00000000;
    mov.f32 %f35, 0f00000000;
    mov.f32 %f36, 0f00000000;
    mov.f32 %f37, 0f00000000;
    mov.f32 %f38, 0f00000000;
    mov.f32 %f39, 0f00000000;
    mov.f32 %f40, 0f00000000;
    mov.f32 %f41, 0f00000000;
    mov.f32 %f42, 0f00000000;
    mov.f32 %f43, 0f00000000;
    mov.f32 %f44, 0f00000000;
    mov.f32 %f45, 0f00000000;
    mov.f32 %f46, 0f00000000;
    mov.f32 %f47, 0f00000000;
    mov.f32 %f48, 0f00000000;
    mov.f32 %f49, 0f00000000;
    mov.f32 %f50, 0f00000000;
    mov.f32 %f51, 0f00000000;
    mov.f32 %f52, 0f00000000;
    mov.f32 %f53, 0f00000000;
    mov.f32 %f54, 0f00000000;
    mov.f32 %f55, 0f00000000;
    mov.u32 %r21, 0;                        // ic = 0
    // Prologue: asynchronously prefetch ic=0 weights (transposed, tap-major/
    // oc-contiguous) into wtile buffer 0 with 4B cp.async copies.
    mov.u32 %r36, %r4;
W0_LOOP:
    setp.ge.u32 %p2, %r36, 648;
    @%p2 bra W0_DONE;
    rem.u32 %r37, %r36, 27;               // tap
    div.u32 %r38, %r36, 27;               // oc
    mul.wide.u32 %rd18, %r36, 4;
    add.s64 %rd19, %rd1, %rd18;           // w + r36*4 (ic = 0)
    mad.lo.u32 %r39, %r37, 24, %r38;      // tap*24 + oc
    mul.lo.u32 %r39, %r39, 4;
    add.u32 %r39, %r35, %r39;             // wtile buffer 0
    cp.async.ca.shared.global [%r39], [%rd19], 4;
    add.u32 %r36, %r36, %r3;
    bra W0_LOOP;
W0_DONE:
    cp.async.commit_group;
IC_LOOP:
    setp.ge.u32 %p1, %r21, 48;
    @%p1 bra IC_DONE;
    // rd4 = in + (b*48 + ic) * 884736 * 4   (input plane base)
    mad.lo.u32 %r22, %r10, 48, %r21;
    mul.lo.u32 %r22, %r22, 884736;
    mul.wide.u32 %rd5, %r22, 4;
    add.s64 %rd4, %rd0, %rd5;
    // r47 = current wtile buffer base = wtile + (ic&1)*2592
    and.b32 %r23, %r21, 1;
    mul.lo.u32 %r23, %r23, 2592;
    add.u32 %r47, %r35, %r23;
    // Async prefetch of the four candidate input rows for kz = kz_lo into
    // inrow buffer 0: inrow[j][ix] holds input row iy = y0 + j - 2.
    // tid<96 -> j = tid/24, ix = (tid%24)*4; edge rows use cp.async zero-fill.
    add.s32 %r25, %r12, %r15;
    sub.s32 %r25, %r25, 2;                  // iz = z + kz_lo - 2 (valid by bounds)
    mul.lo.u32 %r26, %r25, 36864;           // iz * 96 * 96 * 4 (bytes)
    cvt.u64.u32 %rd8, %r26;
    add.s64 %rd9, %rd4, %rd8;               // input slice base
    setp.lt.u32 %p4, %r4, 96;               // vector staging lane
    div.u32 %r27, %r4, 24;                  // j = tid / 24 (0..3)
    rem.u32 %r28, %r4, 24;                  // chunk = tid % 24
    shl.b32 %r28, %r28, 2;                  // ix = chunk * 4
    add.s32 %r29, %r13, %r27;
    sub.s32 %r29, %r29, 2;                  // iy = y0 + j - 2
    setp.ge.s32 %p7, %r29, 0;
    setp.lt.s32 %p8, %r29, 96;
    and.pred %p9, %p7, %p8;                 // valid input row
    and.pred %p10, %p9, %p4;                // valid 16B copy
    mul.lo.u32 %r30, %r29, 384;             // iy * 96 * 4 (bytes)
    cvt.u64.u32 %rd10, %r30;
    add.s64 %rd11, %rd9, %rd10;             // row base (read only if p10)
    mul.wide.u32 %rd12, %r28, 4;            // ix * 4 (16B aligned)
    add.s64 %rd13, %rd11, %rd12;
    mul.lo.u32 %r31, %r27, 96;
    add.u32 %r31, %r31, %r28;               // inrow element j*96 + ix
    mul.lo.u32 %r31, %r31, 4;
    add.u32 %r41, %r40, %r31;               // buffer 0, 16B aligned
    selp.u32 %r32, 16, 0, %p10;             // src-size 0 -> zero-fill edge rows
    @%p4 cp.async.cg.shared.global [%r41], [%rd13], 16, %r32;
    cp.async.commit_group;
    mov.s32 %r24, %r15;                     // kz = kz_lo
KZ_LOOP:
    setp.gt.s32 %p3, %r24, %r16;
    @%p3 bra KZ_DONE;
    // ---- async prefetch: weights for ic+1 (first kz iteration only) ----
    setp.ne.s32 %p2, %r24, %r15;
    @%p2 bra W_PF_DONE;
    setp.ge.u32 %p2, %r21, 47;              // no ic+1 beyond 47
    @%p2 bra W_PF_DONE;
    add.u32 %r23, %r21, 1;
    mul.lo.u32 %r23, %r23, 2592;
    cvt.u64.u32 %rd7, %r23;
    add.s64 %rd6, %rd1, %rd7;               // weight base for ic+1
    and.b32 %r26, %r21, 1;
    xor.b32 %r26, %r26, 1;                  // (ic+1)&1
    mul.lo.u32 %r26, %r26, 2592;
    add.u32 %r44, %r35, %r26;               // alternate wtile buffer base
    mov.u32 %r36, %r4;
W_PF_LOOP:
    setp.ge.u32 %p2, %r36, 648;
    @%p2 bra W_PF_DONE;
    rem.u32 %r37, %r36, 27;               // tap
    div.u32 %r38, %r36, 27;               // oc
    mul.wide.u32 %rd18, %r36, 4;
    add.s64 %rd19, %rd6, %rd18;
    mad.lo.u32 %r39, %r37, 24, %r38;      // tap*24 + oc
    mul.lo.u32 %r39, %r39, 4;
    add.u32 %r39, %r44, %r39;
    cp.async.ca.shared.global [%r39], [%rd19], 4;
    add.u32 %r36, %r36, %r3;
    bra W_PF_LOOP;
W_PF_DONE:
    // ---- async prefetch: input rows for kz+1 into alternate inrow buffer ----
    setp.ge.s32 %p2, %r24, %r16;            // kz >= kz_hi -> nothing to prefetch
    @%p2 bra IR_PF_DONE;
    add.s32 %r25, %r12, %r24;
    sub.s32 %r25, %r25, 1;                  // iz_next = z + (kz+1) - 2
    mul.lo.u32 %r26, %r25, 36864;
    cvt.u64.u32 %rd8, %r26;
    add.s64 %rd9, %rd4, %rd8;
    setp.lt.u32 %p4, %r4, 96;
    div.u32 %r27, %r4, 24;
    rem.u32 %r28, %r4, 24;
    shl.b32 %r28, %r28, 2;
    add.s32 %r29, %r13, %r27;
    sub.s32 %r29, %r29, 2;                  // iy
    setp.ge.s32 %p7, %r29, 0;
    setp.lt.s32 %p8, %r29, 96;
    and.pred %p9, %p7, %p8;
    and.pred %p10, %p9, %p4;
    mul.lo.u32 %r30, %r29, 384;
    cvt.u64.u32 %rd10, %r30;
    add.s64 %rd11, %rd9, %rd10;
    mul.wide.u32 %rd12, %r28, 4;
    add.s64 %rd13, %rd11, %rd12;
    sub.s32 %r31, %r24, %r15;
    add.s32 %r31, %r31, 1;
    and.b32 %r31, %r31, 1;                  // (kz+1-kz_lo)&1
    mul.lo.u32 %r31, %r31, 1536;
    add.u32 %r45, %r40, %r31;               // next inrow buffer base
    mul.lo.u32 %r31, %r27, 96;
    add.u32 %r31, %r31, %r28;
    mul.lo.u32 %r31, %r31, 4;
    add.u32 %r41, %r45, %r31;
    selp.u32 %r32, 16, 0, %p10;
    @%p4 cp.async.cg.shared.global [%r41], [%rd13], 16, %r32;
IR_PF_DONE:
    cp.async.commit_group;                  // exactly one group per kz iteration
    cp.async.wait_group 1;                  // previous stage (rows/weights) ready
    bar.sync 0;
    // r46 = current inrow buffer base = inrow + ((kz-kz_lo)&1)*1536
    sub.s32 %r31, %r24, %r15;
    and.b32 %r31, %r31, 1;
    mul.lo.u32 %r31, %r31, 1536;
    add.u32 %r46, %r40, %r31;
    mov.u32 %r27, 0;                        // ky = 0 (zero-filled rows keep edges exact)
KY_LOOP:
    setp.gt.u32 %p5, %r27, 2;
    @%p5 bra KY_DONE;
    // row A shared base: inrow_buf + (ky*96 + x + kx_lo - 2)*4 ; row B reads row ky+1
    mul.lo.u32 %r29, %r27, 96;
    add.s32 %r29, %r29, %r14;
    add.s32 %r29, %r29, %r19;
    sub.s32 %r29, %r29, 2;
    mul.lo.u32 %r29, %r29, 4;
    add.u32 %r42, %r46, %r29;
    add.u32 %r43, %r42, 384;                // row B staged input pointer
    // packed shared-memory weight tap: t = 26 - (kz*9 + ky*3 + kx_lo), shared by both rows
    mul.lo.u32 %r30, %r24, 9;
    mad.lo.u32 %r30, %r27, 3, %r30;
    add.s32 %r30, %r30, %r19;
    mov.u32 %r32, 26;
    sub.s32 %r30, %r32, %r30;
    mul.lo.u32 %r30, %r30, 96;              // tap stride = 24 oc * 4 B
    add.u32 %r36, %r47, %r30;               // packed weight tap pointer
    mov.s32 %r31, %r19;                     // kx = kx_lo
KX_LOOP:
    setp.gt.s32 %p7, %r31, %r20;
    @%p7 bra KX_DONE;
    ld.shared.f32 %f24, [%r42];             // row A staged input
    ld.shared.f32 %f56, [%r43];             // row B staged input
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36];
    fma.rn.f32 %f0,  %f24, %f25, %f0;
    fma.rn.f32 %f1,  %f24, %f26, %f1;
    fma.rn.f32 %f2,  %f24, %f27, %f2;
    fma.rn.f32 %f3,  %f24, %f28, %f3;
    fma.rn.f32 %f32, %f56, %f25, %f32;
    fma.rn.f32 %f33, %f56, %f26, %f33;
    fma.rn.f32 %f34, %f56, %f27, %f34;
    fma.rn.f32 %f35, %f56, %f28, %f35;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+16];
    fma.rn.f32 %f4,  %f24, %f25, %f4;
    fma.rn.f32 %f5,  %f24, %f26, %f5;
    fma.rn.f32 %f6,  %f24, %f27, %f6;
    fma.rn.f32 %f7,  %f24, %f28, %f7;
    fma.rn.f32 %f36, %f56, %f25, %f36;
    fma.rn.f32 %f37, %f56, %f26, %f37;
    fma.rn.f32 %f38, %f56, %f27, %f38;
    fma.rn.f32 %f39, %f56, %f28, %f39;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+32];
    fma.rn.f32 %f8,  %f24, %f25, %f8;
    fma.rn.f32 %f9,  %f24, %f26, %f9;
    fma.rn.f32 %f10, %f24, %f27, %f10;
    fma.rn.f32 %f11, %f24, %f28, %f11;
    fma.rn.f32 %f40, %f56, %f25, %f40;
    fma.rn.f32 %f41, %f56, %f26, %f41;
    fma.rn.f32 %f42, %f56, %f27, %f42;
    fma.rn.f32 %f43, %f56, %f28, %f43;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+48];
    fma.rn.f32 %f12, %f24, %f25, %f12;
    fma.rn.f32 %f13, %f24, %f26, %f13;
    fma.rn.f32 %f14, %f24, %f27, %f14;
    fma.rn.f32 %f15, %f24, %f28, %f15;
    fma.rn.f32 %f44, %f56, %f25, %f44;
    fma.rn.f32 %f45, %f56, %f26, %f45;
    fma.rn.f32 %f46, %f56, %f27, %f46;
    fma.rn.f32 %f47, %f56, %f28, %f47;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+64];
    fma.rn.f32 %f16, %f24, %f25, %f16;
    fma.rn.f32 %f17, %f24, %f26, %f17;
    fma.rn.f32 %f18, %f24, %f27, %f18;
    fma.rn.f32 %f19, %f24, %f28, %f19;
    fma.rn.f32 %f48, %f56, %f25, %f48;
    fma.rn.f32 %f49, %f56, %f26, %f49;
    fma.rn.f32 %f50, %f56, %f27, %f50;
    fma.rn.f32 %f51, %f56, %f28, %f51;
    ld.shared.v4.f32 {%f25, %f26, %f27, %f28}, [%r36+80];
    fma.rn.f32 %f20, %f24, %f25, %f20;
    fma.rn.f32 %f21, %f24, %f26, %f21;
    fma.rn.f32 %f22, %f24, %f27, %f22;
    fma.rn.f32 %f23, %f24, %f28, %f23;
    fma.rn.f32 %f52, %f56, %f25, %f52;
    fma.rn.f32 %f53, %f56, %f26, %f53;
    fma.rn.f32 %f54, %f56, %f27, %f54;
    fma.rn.f32 %f55, %f56, %f28, %f55;
    add.u32 %r42, %r42, 4;                  // next staged input column (row A)
    add.u32 %r43, %r43, 4;                  // next staged input column (row B)
    sub.u32 %r36, %r36, 96;                 // previous packed weight tap
    add.s32 %r31, %r31, 1;
    bra KX_LOOP;
KX_DONE:
    add.u32 %r27, %r27, 1;
    bra KY_LOOP;
KY_DONE:
    bar.sync 0;                             // consumed buffer can be overwritten by later prefetches
    add.s32 %r24, %r24, 1;
    bra KZ_LOOP;
KZ_DONE:
    add.s32 %r21, %r21, 1;
    bra IC_LOOP;
IC_DONE:
    @!%p6 bra DONE;                         // inactive lanes never store
    setp.eq.u32 %p5, %r1, 0;
    @%p5 bra STORE;
    ld.global.f32 %f25, [%rd2];
    add.f32 %f0,  %f0,  %f25;
    add.f32 %f32, %f32, %f25;
    ld.global.f32 %f25, [%rd2+4];
    add.f32 %f1,  %f1,  %f25;
    add.f32 %f33, %f33, %f25;
    ld.global.f32 %f25, [%rd2+8];
    add.f32 %f2,  %f2,  %f25;
    add.f32 %f34, %f34, %f25;
    ld.global.f32 %f25, [%rd2+12];
    add.f32 %f3,  %f3,  %f25;
    add.f32 %f35, %f35, %f25;
    ld.global.f32 %f25, [%rd2+16];
    add.f32 %f4,  %f4,  %f25;
    add.f32 %f36, %f36, %f25;
    ld.global.f32 %f25, [%rd2+20];
    add.f32 %f5,  %f5,  %f25;
    add.f32 %f37, %f37, %f25;
    ld.global.f32 %f25, [%rd2+24];
    add.f32 %f6,  %f6,  %f25;
    add.f32 %f38, %f38, %f25;
    ld.global.f32 %f25, [%rd2+28];
    add.f32 %f7,  %f7,  %f25;
    add.f32 %f39, %f39, %f25;
    ld.global.f32 %f25, [%rd2+32];
    add.f32 %f8,  %f8,  %f25;
    add.f32 %f40, %f40, %f25;
    ld.global.f32 %f25, [%rd2+36];
    add.f32 %f9,  %f9,  %f25;
    add.f32 %f41, %f41, %f25;
    ld.global.f32 %f25, [%rd2+40];
    add.f32 %f10, %f10, %f25;
    add.f32 %f42, %f42, %f25;
    ld.global.f32 %f25, [%rd2+44];
    add.f32 %f11, %f11, %f25;
    add.f32 %f43, %f43, %f25;
    ld.global.f32 %f25, [%rd2+48];
    add.f32 %f12, %f12, %f25;
    add.f32 %f44, %f44, %f25;
    ld.global.f32 %f25, [%rd2+52];
    add.f32 %f13, %f13, %f25;
    add.f32 %f45, %f45, %f25;
